// Included only in an isolated QA copy of the production frontendDist. The
// private module is generated by the fixture owner and never shipped.
import fixtures from './qa-fixtures.private.mjs';

const output = document.createElement('textarea');
output.id = 'qa-delete-observations';
output.setAttribute('aria-label', 'QA delete observations');
output.readOnly = true;
Object.assign(output.style, {position:'fixed', bottom:'0', right:'0', width:'4px', height:'4px', pointerEvents:'none'});
document.body.append(output);
const samples = {}, events = {};
let state = 'starting';
const report = () => { output.value = JSON.stringify({state, samples, events}); };
const stamp = () => ({mono:performance.now(), epoch:Date.now(), visible:document.visibilityState === 'visible'});

async function observe() {
  const ipc = window.__TAURI_INTERNALS__;
  if (!ipc || location.hostname !== 'tauri.localhost') throw Error('Expected native WebView');
  if (fixtures.length !== 20 || new Set(fixtures.map(f => f.assetId)).size !== 20) throw Error('Expected twenty different run-owned assets');
  const settings = await ipc.invoke('get_backup_settings');
  if (settings?.provider_type !== 'telegram' || !settings.enabled || !settings.can_delete_owned_media) throw Error('Expected enabled QA space');
  // A newly prepared QA database may still be uploading this exact batch
  // through the production queue. No delete is allowed until all receipts exist.
  let ops;
  const deadline = performance.now() + 60 * 60_000;
  for (;;) {
    ops = await ipc.invoke('list_backup_operations');
    const uploads = fixtures.map(f => ops.find(o => o.space_id === settings.space_id &&
      o.kind === 'upload' && o.operation_id === f.uploadId && o.asset_id === f.assetId));
    if (uploads.some(o => !o || ['blocked','canceled'].includes(o.state))) throw Error('Fixture upload missing or blocked');
    if (uploads.every(o => o.state === 'completed')) break;
    if (performance.now() >= deadline) throw Error('Fixture uploads timed out');
    state = 'uploading'; report();
    await new Promise(resolve => setTimeout(resolve, 3000));
  }
  const assets = await ipc.invoke('list_backup_assets', {spaceId:settings.space_id});
  const owned = new Set();
  for (const fixture of fixtures) {
    const a = assets.find(a => a.asset_id === fixture.assetId);
    const scoped = ops.filter(o => o.space_id === settings.space_id && o.asset_id === fixture.assetId);
    if (!a || a.space_id !== settings.space_id || a.task_id || a.remote_deleted ||
        a.local_state !== 'present' || a.remote_state !== 'backed_up' ||
        a.content_sha256 !== fixture.sha256 || a.path !== fixture.path ||
        !scoped.some(o => o.kind === 'upload' && o.operation_id === fixture.uploadId && o.state === 'completed') ||
        scoped.some(o => o.kind === 'delete')) throw Error('Fixture preflight mismatch');
    owned.add(fixture.assetId);
  }
  await ipc.invoke('plugin:event|listen', {event:'backup_asset_deleted', target:{kind:'Any'},
    handler:ipc.transformCallback(event => {events[event.payload] = stamp(); report();})});
  let selected;
  document.addEventListener('contextmenu', event => {
    selected = event.target.closest('[data-asset-id]')?.dataset.assetId;
  }, true);
  document.addEventListener('click', event => {
    if (event.target.closest('[role="menuitem"]')?.textContent.trim() !== '从当前同步库删除') return;
    if (!event.isTrusted || !owned.has(selected) || samples[selected]) {
      event.preventDefault(); event.stopImmediatePropagation(); return;
    }
    samples[selected] = {click:stamp()};
    report();
  }, true);
  const onRender = () => {
    for (const row of document.querySelectorAll('[data-asset-id]')) {
      if (!row.id && owned.has(row.dataset.assetId)) row.id = 'qa-fixture-' + row.dataset.assetId;
    }
    for (const [assetId, sample] of Object.entries(samples)) {
      if (!sample.removed && !document.getElementById('qa-fixture-' + assetId)) {
        sample.removed = stamp();
        requestAnimationFrame(() => {sample.frame = stamp(); report();});
        report();
      }
    }
  };
  new MutationObserver(onRender).observe(document.body, {subtree:true, childList:true});
  onRender();
  state = 'ready'; report();
  // The production list paginates on scroll. Mount the whole fixture batch
  // before timing so a view change cannot be mistaken for deletion.
  const loading = setInterval(() => {
    const panel = document.querySelector('.task-list')?.closest('[role="tabpanel"]');
    if (!panel) return;
    if (fixtures.every(f => document.getElementById('qa-fixture-' + f.assetId))) {
      clearInterval(loading); state = 'mounted'; report(); return;
    }
    panel.scrollTop = panel.scrollHeight;
  }, 300);
}
observe().catch(error => {state = error.message; report();});
